import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {adminApi,passwordHash} from '../src/kafra-admin.js';
import {localD1} from '../tools/local-d1.mjs';
const schema=await readFile(new URL('../kafra-schema.sql',import.meta.url),'utf8');
async function fixture(t){const DB=localD1(schema);t.after(()=>DB.close());const pepper='p'.repeat(43),salt='a'.repeat(32),password='a-long-test-only-password';
  return {DB,KAFRA_ADMIN_USER:'admin',KAFRA_DATA_KEY:'A'.repeat(43),KAFRA_ADMIN_PEPPER:pepper,KAFRA_ADMIN_HASH:salt+':'+await passwordHash(password,salt,pepper),password};}
const request=(path,body,cookie)=>new Request('https://guard.example.test/api/'+path,{method:body===undefined?'GET':'POST',headers:{Origin:'https://guard.example.test','Content-Type':'application/json',...(cookie?{Cookie:cookie}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});
async function login(env){const response=await adminApi(request('login',{username:'admin',password:env.password}),env);assert.equal(response.status,200);return response.headers.get('Set-Cookie').split(';')[0];}
test('Super Admin login uses HttpOnly Secure cookie; session table stores only token hash',async t=>{const env=await fixture(t);
  const response=await adminApi(request('login',{username:'admin',password:env.password}),env);assert.equal(response.status,200);
  const cookie=response.headers.get('Set-Cookie');for(const flag of ['HttpOnly','Secure','SameSite=Strict','Path=/'])assert.ok(cookie.includes(flag));
  const token=cookie.split(';')[0],me=await adminApi(request('me',undefined,token),env);assert.equal((await me.json()).role,'super_admin');
  const rows=(await env.DB.prepare('SELECT * FROM kafra_admin_sessions').all()).results;assert.equal(rows.length,1);assert.equal(rows[0].token_hash.length,64);assert.ok(!JSON.stringify(rows).includes(token.split('=')[1]));
});
test('Unauthenticated sessions and arbitrary legacy bearer tokens cannot access owner data',async t=>{const env=await fixture(t);
  assert.equal((await adminApi(request('sessions'),env)).status,401);
  assert.equal((await adminApi(new Request('https://guard.example.test/api/sessions',{headers:{Authorization:'Bearer '+'x'.repeat(43)}}),env)).status,401);
});
test('CSRF origin is required for login/logout; wrong password is rejected and throttled',async t=>{const env=await fixture(t);
  assert.equal((await adminApi(new Request('https://guard.example.test/api/login',{method:'POST',body:'{}'}),env)).status,403);
  for(let i=0;i<10;i++)assert.equal((await adminApi(request('login',{username:'admin',password:'wrong'}),env)).status,401);
  assert.equal((await adminApi(request('login',{username:'admin',password:env.password}),env)).status,429);
});
test('Password rotation and logout revoke owner sessions',async t=>{const env=await fixture(t),cookie=await login(env);
  assert.equal((await adminApi(request('me',undefined,cookie),{...env,KAFRA_ADMIN_PEPPER:'new'.repeat(20)})).status,401);
  assert.equal((await adminApi(request('logout',{},cookie),env)).status,200);assert.equal((await adminApi(request('me',undefined,cookie),env)).status,401);
});
test('Authenticated owner sees explicit unconfigured gate, never sample player data',async t=>{const env=await fixture(t),cookie=await login(env);
  const response=await adminApi(request('sessions',undefined,cookie),env);assert.equal(response.status,503);assert.equal((await response.json()).error,'gate_not_configured');
});
const gateKey='c'.repeat(64),otherKey='d'.repeat(64);
async function ownerSetup(env){const admin=await login(env);
  const make=async(name,gate,key)=>{const {id}=await (await adminApi(request('admin/servers',{name},admin),env)).json();
    assert.equal((await adminApi(request('admin/servers/kafra',{id,enabled:true,gateUrl:gate,gateKey:key,plan:'pro'},admin),env)).status,200);return id;};
  const own=await make('Sovereign RO','https://gate.sovereign.test/',gateKey),other=await make('Other RO','https://gate.other.test/',otherKey);
  assert.equal((await adminApi(request('admin/owners',{username:'sov.owner',password:'owner-pass-1234',serverId:own},admin),env)).status,201);
  const response=await adminApi(request('login',{username:'sov.owner',password:'owner-pass-1234'}),env);assert.equal(response.status,200);
  return {admin,own,other,owner:response.headers.get('Set-Cookie').split(';')[0]};}
test('Super Admin creates servers and Server Owners; gate keys are sealed in D1',async t=>{const env=await fixture(t),{own}=await ownerSetup(env);
  const row=await env.DB.prepare('SELECT gate_key FROM kafra_servers WHERE id=?').bind(own).first();assert.ok(!row.gate_key.includes(gateKey));
  const owner=await env.DB.prepare('SELECT password_hash FROM kafra_owners WHERE username=?').bind('sov.owner').first();assert.ok(!owner.password_hash.includes('owner-pass'));
});
test('Server Owner sees only its own server and cannot reach Super Admin routes',async t=>{const env=await fixture(t),{own,other,owner}=await ownerSetup(env);
  const me=await (await adminApi(request('me',undefined,owner),env)).json();assert.equal(me.role,'server_owner');assert.deepEqual(me.servers.map(s=>s.id),[own]);
  assert.equal((await adminApi(request('admin/servers',undefined,owner),env)).status,403);
  assert.equal((await adminApi(request('admin/owners',{username:'evil.owner',password:'x'.repeat(20),serverId:other},owner),env)).status,403);
  for(const server of ['default',other])assert.equal((await adminApi(request('sessions?server='+server,undefined,owner),env)).status,404);
  const original=globalThis.fetch;t.after(()=>{globalThis.fetch=original;});let seen;
  globalThis.fetch=async(url,init)=>{seen={url:String(url),auth:init.headers.Authorization};return new Response(JSON.stringify({total:0,offset:0,sessions:[]}));};
  const response=await adminApi(request('sessions',undefined,owner),env);assert.equal(response.status,200);
  assert.equal(seen.url,'https://gate.sovereign.test/internal/owner/sessions?offset=0');assert.equal(seen.auth,'Bearer '+gateKey);
});
test('Owner accounts are validated, and deleting an owner or server revokes its sessions',async t=>{const env=await fixture(t),{admin,own,owner}=await ownerSetup(env);
  for(const [body,error] of [[{username:'admin',password:'x'.repeat(20),serverId:own},'invalid_username'],[{username:'short.pw',password:'x'.repeat(11),serverId:own},'weak_password'],[{username:'sov.owner',password:'x'.repeat(20),serverId:own},'username_taken']]){
    const response=await adminApi(request('admin/owners',body,admin),env);assert.equal((await response.json()).error,error);}
  assert.equal((await adminApi(request('login',{username:'nobody.here',password:'whatever-pass'}),env)).status,401);
  assert.equal((await adminApi(request('admin/owners/delete',{username:'sov.owner'},admin),env)).status,200);
  assert.equal((await adminApi(request('me',undefined,owner),env)).status,401);
  assert.equal((await adminApi(request('admin/servers/delete',{id:own},admin),env)).status,200);
  assert.equal((await (await adminApi(request('admin/servers',undefined,admin),env)).json()).servers.length,1);
});
const ingest=(kind,key,body)=>new Request('https://guard.example.test/api/ingest/moro/'+kind,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+key},body:JSON.stringify(body)});
test('Products are opt-in: an owner sees nothing until Kafra Guard or Mobile RO is enabled',async t=>{const env=await fixture(t),admin=await login(env);
  const {id}=await (await adminApi(request('admin/servers',{name:'Bare RO'},admin),env)).json();
  await adminApi(request('admin/owners',{username:'bare.owner',password:'owner-pass-1234',serverId:id},admin),env);
  const owner=(await adminApi(request('login',{username:'bare.owner',password:'owner-pass-1234'}),env)).headers.get('Set-Cookie').split(';')[0];
  assert.deepEqual((await (await adminApi(request('me',undefined,owner),env)).json()).servers,[{id,name:'Bare RO',kafra:false,moro:false,kafraPlan:'basic',limits:{realms:1,allowRules:10,maxOnline:50}}]);
  assert.equal((await adminApi(request('sessions',undefined,owner),env)).status,404);assert.equal((await adminApi(request('moro',undefined,owner),env)).status,404);
  assert.equal((await adminApi(request('admin/servers/kafra',{id,enabled:true,gateUrl:'https://gate.bare.test/',gateKey:''},admin),env)).status,400);
});
test('Mobile RO: ingest key is shown once, app reports reach only that server owner dashboard',async t=>{const env=await fixture(t),{admin,own,other,owner}=await ownerSetup(env);
  const enable=async(id,extra={})=>(await (await adminApi(request('admin/servers/moro',{id,enabled:true,plan:'Standard',expiresAt:'2099-12-31',...extra},admin),env)).json()).ingestKey;
  const key=await enable(own),otherKey=await enable(other);assert.match(key,/^[A-Za-z0-9_-]{43}$/);assert.equal(await enable(own),null);
  const stored=await env.DB.prepare('SELECT moro_key_hash FROM kafra_servers WHERE id=?').bind(own).first();assert.notEqual(stored.moro_key_hash,key);
  assert.equal((await adminApi(request('admin/moro/builds',{serverId:own,version:'1.4.2',url:'https://cdn.test/moro.apk',notes:'Fixes'},admin),env)).status,201);
  assert.equal((await adminApi(request('admin/moro/builds',{serverId:own,version:'1.4.3',url:'http://cdn.test/moro.apk'},admin),env)).status,400);
  for(const device of ['phone-a','phone-b'])assert.equal((await adminApi(ingest('heartbeat',key,{deviceId:device,appVersion:'1.4.2',os:'Android 14'}),env)).status,200);
  assert.equal((await adminApi(ingest('heartbeat',otherKey,{deviceId:'phone-z',appVersion:'1.0.0',os:'Android 13'}),env)).status,200);
  assert.equal((await adminApi(ingest('crash',key,{appVersion:'1.4.2',os:'Android 14',model:'Pixel 8',message:'NullPointerException',stack:'at a.b(C.java:1)'}),env)).status,201);
  assert.equal((await adminApi(ingest('heartbeat','x'.repeat(43),{deviceId:'d',appVersion:'1',os:'A'}),env)).status,401);
  assert.equal((await adminApi(ingest('crash',key,{appVersion:'1.4.2',os:'Android 14'}),env)).status,400);
  const data=await (await adminApi(request('moro',undefined,owner),env)).json();
  assert.equal(data.license.plan,'Standard');assert.equal(data.license.active,true);assert.equal(data.builds[0].version,'1.4.2');
  assert.deepEqual([data.stats.online,data.stats.devices24h,data.stats.crashes24h],[2,2,1]);assert.equal(data.crashes[0].model,'Pixel 8');
  assert.equal((await adminApi(request('moro?server='+other,undefined,owner),env)).status,404);
  const rotated=await enable(own,{rotateKey:true});assert.notEqual(rotated,key);
  assert.equal((await adminApi(ingest('heartbeat',key,{deviceId:'phone-a',appVersion:'1.4.2',os:'Android 14'}),env)).status,401);
  assert.equal((await adminApi(request('admin/servers/moro',{id:own,enabled:false},admin),env)).status,200);
  assert.equal((await adminApi(request('moro',undefined,owner),env)).status,404);
});
const sso={GOOGLE_CLIENT_ID:'g-id',GOOGLE_CLIENT_SECRET:'g-secret',DISCORD_CLIENT_ID:'d-id',DISCORD_CLIENT_SECRET:'d-secret'};
// Fake provider: the token endpoint records the form; the profile endpoint returns whoever `profile.current` is.
function fakeProviders(t,profile){const original=globalThis.fetch;t.after(()=>{globalThis.fetch=original;});const seen=[];
  globalThis.fetch=async(url,init)=>{url=String(url);
    if(url.includes('token')){seen.push(Object.fromEntries(new URLSearchParams(String(init.body))));return new Response(JSON.stringify({access_token:'access-'+seen.length}));}
    return new Response(JSON.stringify(profile.current));};return seen;}
async function oauth(env,provider,mode,cookie){
  const start=await adminApi(request('oauth/'+provider+'/start?mode='+mode,undefined,cookie),env);assert.equal(start.status,302);
  if(start.headers.get('Location').startsWith('/'))return {location:start.headers.get('Location')};
  const location=new URL(start.headers.get('Location'));
  const callback=await adminApi(request('oauth/'+provider+'/callback?code=abc&state='+location.searchParams.get('state')),env);
  return {start:location,state:location.searchParams.get('state'),location:callback.headers.get('Location'),cookie:callback.headers.get('Set-Cookie')?.split(';')[0]};}
test('Google/Discord sign-in uses the account that linked it in Settings',async t=>{const env={...await fixture(t),...sso},{owner}=await ownerSetup(env);
  const profile={current:{sub:'google-123',email:'owner@gmail.test',email_verified:true}},seen=fakeProviders(t,profile);
  assert.deepEqual((await (await adminApi(request('providers'),env)).json()).providers,['google','discord']);
  const linked=await oauth(env,'google','link',owner);assert.equal(linked.location,'/#linked=google');
  assert.ok(linked.start.searchParams.get('code_challenge'));assert.ok(seen.at(-1).code_verifier);assert.equal(seen.at(-1).redirect_uri,'https://guard.example.test/api/oauth/google/callback');
  const me=await (await adminApi(request('me',undefined,owner),env)).json();assert.deepEqual(me.identities.map(i=>[i.provider,i.label]),[['google','owner@gmail.test']]);
  const signedIn=await oauth(env,'google','login');assert.equal(signedIn.location,'/#signed_in');
  assert.equal((await (await adminApi(request('me',undefined,signedIn.cookie),env)).json()).username,'sov.owner');
  assert.equal((await adminApi(request('oauth/google/callback?code=abc&state='+signedIn.state),env)).headers.get('Location'),'/#sso_error=expired');
  const admin=await login(env);assert.equal((await oauth(env,'google','link',admin)).location,'/#sso_error=already_linked');
  profile.current={sub:'google-999',email:'x@gmail.test',email_verified:false};assert.equal((await oauth(env,'google','login')).location,'/#sso_error=provider');
  profile.current={id:'discord-42',username:'tata'};assert.equal((await oauth(env,'discord','link',admin)).location,'/#linked=discord');
  assert.equal((await (await adminApi(request('me',undefined,(await oauth(env,'discord','login')).cookie),env)).json()).role,'super_admin');
  assert.equal((await oauth(env,'discord','link')).location,'/#sso_error=signin_first');
  assert.equal((await adminApi(request('identities/unlink',{provider:'discord'},admin),env)).status,200);
  assert.equal((await (await adminApi(request('me',undefined,(await oauth(env,'discord','login')).cookie),env)).json()).role,'member');
  await adminApi(request('admin/owners/delete',{username:'sov.owner'},admin),env);
  profile.current={sub:'google-123',email:'owner@gmail.test',email_verified:true};
  assert.equal((await (await adminApi(request('me',undefined,(await oauth(env,'google','login')).cookie),env)).json()).role,'member');
});
test('Google/Discord sign-up creates a member who sees no server',async t=>{const env={...await fixture(t),...sso},{own}=await ownerSetup(env);
  const profile={current:{id:'discord-7',username:'newbie'}};fakeProviders(t,profile);
  const first=await oauth(env,'discord','login');assert.equal(first.location,'/#signed_in');
  const me=await (await adminApi(request('me',undefined,first.cookie),env)).json();
  assert.equal(me.role,'member');assert.equal(me.name,'newbie');assert.match(me.username,/^member-[a-f0-9]{12}$/);assert.deepEqual(me.servers,[]);
  assert.equal((await (await adminApi(request('me',undefined,(await oauth(env,'discord','login')).cookie),env)).json()).username,me.username);
  for(const path of ['sessions','sessions?server='+own,'modules?server=default','moro?server='+own])assert.equal((await adminApi(request(path,undefined,first.cookie),env)).status,404);
  assert.equal((await adminApi(request('admin/servers',undefined,first.cookie),env)).status,403);
  assert.equal((await adminApi(request('identities/unlink',{provider:'discord'},first.cookie),env)).status,400);
  const admin=await login(env);
  assert.equal((await adminApi(request('admin/owners',{username:me.username,password:'another-long-password',serverId:own},admin),env)).status,400);
});
test('SSO buttons stay off until a provider is configured',async t=>{const env=await fixture(t);
  assert.deepEqual((await (await adminApi(request('providers'),env)).json()).providers,[]);
  assert.equal((await adminApi(request('oauth/google/start?mode=login'),env)).headers.get('Location'),'/#sso_error=unavailable');
});
test('client limits are read and set on the owner gate; other servers and bad values are refused',async t=>{const env=await fixture(t),{own,other,owner}=await ownerSetup(env);
  const original=globalThis.fetch;t.after(()=>{globalThis.fetch=original;});const seen=[];
  globalThis.fetch=async(url,init)=>{seen.push({url:String(url),method:init.method??'GET',auth:init.headers.Authorization,body:init.body});
    return new Response(JSON.stringify(init.body?{...JSON.parse(init.body),networkPrefix:24,extra:'x'}:{maxPerDevice:2,maxPerNetwork:0,networkPrefix:24}));};
  assert.deepEqual(await (await adminApi(request('policy?server='+own,undefined,owner),env)).json(),{maxPerDevice:2,maxPerNetwork:0,networkPrefix:24,protection:true});
  assert.equal(seen[0].url,'https://gate.sovereign.test/internal/owner/policy');assert.equal(seen[0].auth,'Bearer '+gateKey);
  const saved=await adminApi(request('policy',{server:own,maxPerDevice:1,maxPerNetwork:4},owner),env);
  assert.deepEqual(await saved.json(),{maxPerDevice:1,maxPerNetwork:4,networkPrefix:24,protection:true});assert.equal(seen[1].method,'POST');assert.equal(seen[1].body,'{"maxPerDevice":1,"maxPerNetwork":4}');
  const off=await adminApi(request('policy',{server:own,protection:false},owner),env);
  assert.equal((await off.json()).protection,false);assert.equal(seen[2].body,'{"protection":false}');
  for(const bad of [{maxPerDevice:0,maxPerNetwork:0},{maxPerDevice:11,maxPerNetwork:0},{maxPerDevice:1,maxPerNetwork:101},{maxPerDevice:'1',maxPerNetwork:0},{protection:'off'},{protection:false,maxPerDevice:1}])
    assert.equal((await adminApi(request('policy',{server:own,...bad},owner),env)).status,400);
  assert.equal((await adminApi(request('policy',{server:other,maxPerDevice:1,maxPerNetwork:0},owner),env)).status,404);
  assert.equal((await adminApi(request('policy',{server:other,protection:false},owner),env)).status,404);
  assert.equal((await adminApi(request('policy?server='+other,undefined,owner),env)).status,404);
  assert.equal(seen.length,3);
  globalThis.fetch=async()=>new Response('',{status:400});
  assert.deepEqual(await (await adminApi(request('policy',{server:own,protection:false},owner),env)).json(),{error:'protection_unsupported'});
  assert.deepEqual(await (await adminApi(request('policy',{server:own,maxPerDevice:1,maxPerNetwork:0},owner),env)).json(),{error:'invalid_limits'});
});
test('kick, ban and unban go to the owner gate only, with validated input',async t=>{const env=await fixture(t),{own,other,owner}=await ownerSetup(env);
  const original=globalThis.fetch;t.after(()=>{globalThis.fetch=original;});const seen=[];
  globalThis.fetch=async(url,init)=>{seen.push({url:String(url),method:init.method??'GET',body:init.body});
    if(String(url).endsWith('/bans'))return new Response(JSON.stringify({bans:[{deviceId:'e'.repeat(64),reason:'Bot',bannedAt:'2026-10-30T00:00:00.000Z',secret:'x'}]}));
    if(String(url).endsWith('/unban'))return new Response('{}',{status:404});
    return new Response(JSON.stringify({endedSessions:1}));};
  const post=(path,data)=>adminApi(request(path,{server:own,...data},owner),env);
  assert.deepEqual(await (await post('kick',{id:'a'.repeat(32)})).json(),{ok:true,endedSessions:1});
  assert.equal(seen[0].url,'https://gate.sovereign.test/internal/owner/kick');assert.equal(seen[0].body,JSON.stringify({id:'a'.repeat(32)}));
  assert.equal((await post('ban',{deviceId:'e'.repeat(64),reason:'  Bot  '})).status,200);assert.equal(seen[1].body,JSON.stringify({deviceId:'e'.repeat(64),reason:'Bot'}));
  assert.deepEqual((await (await adminApi(request('bans?server='+own,undefined,owner),env)).json()).bans,[{deviceId:'e'.repeat(64),reason:'Bot',bannedAt:'2026-10-30T00:00:00.000Z'}]);
  assert.deepEqual(await (await post('unban',{deviceId:'e'.repeat(64)})).json(),{error:'not_banned'});
  const before=seen.length;
  for(const [path,data] of [['kick',{id:'zz'}],['ban',{deviceId:'x'}],['ban',{deviceId:'e'.repeat(64),reason:'a'.repeat(201)}],['ban',{deviceId:'e'.repeat(64),reason:'a\nb'}],['unban',{}]])
    assert.equal((await post(path,data)).status,400,path+JSON.stringify(data));
  assert.equal((await adminApi(request('kick',{server:other,id:'a'.repeat(32)},owner),env)).status,404);
  assert.equal((await adminApi(request('kick?server='+own,undefined,owner),env)).status,404);
  assert.equal(seen.length,before);
});
